frappe.ui.form.on('Task', {
	refresh(frm) {
        // 1. Add a custom inner button to the form
        frm.add_custom_button(__('Start Process'), function() {

            let current_count = 0;
            let total_steps = 100;

            // 2. Show the initial progress bar at 0%
            frappe.show_progress(__('Processing Data'), current_count, total_steps, __('Initializing...'));

            // 3. Create a timer to increment the progress bar every 100 milliseconds
            let progress_timer = setInterval(function() {
                current_count += 5; // Increase progress by 5 each step

                // Update the progress bar with the new count and message
                frappe.show_progress(
                    __('Processing Data'), 
                    current_count, 
                    total_steps, 
                    __('Completed {0} out of {1} tasks', [current_count, total_steps])
                );

                // 4. When it reaches 100%, stop the timer and hide the progress bar
                if (current_count >= total_steps) {
                    clearInterval(progress_timer);

                    // Small delay so the user sees it hit 100% before closing
                    setTimeout(() => {
                        frappe.hide_progress();
                        frappe.msgprint(__('Process completed successfully!'));
                    }, 500);
                }
            }, 100); // 100ms interval controls the speed of the bar

        });
    }
});

